#!/usr/bin/env python3
import argparse,csv,hashlib,json,statistics,wave
from pathlib import Path
import numpy as np
p=argparse.ArgumentParser();p.add_argument('--run',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();components=['prefill','decode','local','codec']
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def audio(path,last):
 w=wave.open(str(path),'rb');m={'channels':w.getnchannels(),'sample_rate_hz':w.getframerate(),'sample_width_bytes':w.getsampwidth(),'frames':w.getnframes(),'duration_seconds':w.getnframes()/w.getframerate()};v=np.frombuffer(w.readframes(w.getnframes()),dtype='<i2').astype(np.float64)/32768.;w.close();assert (m['channels'],m['sample_rate_hz'],m['sample_width_bytes'],m['frames'])==(1,48000,2,last['samples']);return {**m,'sha256':sha(path),'rms':float(np.sqrt(np.mean(v*v))),'peak':float(np.max(np.abs(v))),'finite':bool(np.isfinite(v).all()),'path':str(path.resolve())}
def route(name,expected_provider,wav_name):
 b=json.load(open(a.run/f'{name}-benchmark-result.json'));pr=json.load(open(a.run/f'{name}-profile-result.json'));assert b['result']=='passed' and b['profiling']=='off' and not b['profile_paths'];assert pr['result']=='passed' and pr['profiling']=='detailed';runs=b['runs'];assert len(runs)>=6 and len({x['frames'] for x in runs})==1 and len({x['samples'] for x in runs})==1 and all(x['frames']>0 and x['samples']>0 for x in runs);pframes=[x['frames'] for x in pr['runs']];assert len(pframes)==1
 prof=a.run/f'evidence/{name}-profile-profiles';providers={};physical={}
 for comp,path_s in zip(components,pr['profile_paths']):
  q=list(prof.glob(Path(path_s).name));assert len(q)==1,(name,comp,q);path=q[0];d=json.load(open(path));ev=d if isinstance(d,list) else d.get('traceEvents',[]);nodes=[x for x in ev if x.get('args',{}).get('provider')];ps=sorted({x['args']['provider'] for x in nodes});assert ps==[expected_provider],(name,comp,ps);other='CPUExecutionProvider' if expected_provider=='QNNExecutionProvider' else 'QNNExecutionProvider';assert not any(other in json.dumps(x) for x in ev);providers[comp]={'profile':path.name,'sha256':sha(path),'provider_events':len(nodes),'providers':ps}
  csvs=list(prof.glob(comp+'.qnn.csv'))
  if expected_provider=='CPUExecutionProvider':assert not csvs;continue
  assert len(csvs)==1;rows=list(csv.DictReader(open(csvs[0])));by={}
  for row in rows:
   ident=row.get('Event Identifier','')
   if ident in {'RPC (execute) time','QNN accelerator (execute) time','Accelerator (execute) time (cycles)','Number of HVX threads used'}:by.setdefault(ident,[]).append(int(row['Time']))
  for term in ['RPC (execute) time','QNN accelerator (execute) time','Accelerator (execute) time (cycles)','Number of HVX threads used']:assert by.get(term),(comp,term)
  assert set(by['Number of HVX threads used'])=={4};physical[comp]={'profile':csvs[0].name,'sha256':sha(csvs[0]),'execute_events':len(by['RPC (execute) time']),'rpc_execute_us':by['RPC (execute) time'],'accelerator_execute_us':by['QNN accelerator (execute) time'],'accelerator_execute_cycles':by['Accelerator (execute) time (cycles)'],'hvx_threads':by['Number of HVX threads used']}
 if expected_provider=='QNNExecutionProvider':
  expected={'prefill':1,'codec':1,'decode':sum(pframes),'local':sum(pframes)+sum(x<375 for x in pframes)}
  for c,n in expected.items():assert physical[c]['execute_events']==n,(c,physical[c]['execute_events'],n)
 else:expected={'prefill':1,'codec':1,'decode':sum(pframes),'local':sum(pframes)+sum(x<375 for x in pframes)}
 rtf=[x['rtf'] for x in runs];lat=[x['total_seconds'] for x in runs];fa=[x['first_audio_seconds'] for x in runs]
 return {'benchmark':{'setup_seconds':b['setup_seconds'],'session_setup_seconds':b['session_setup_seconds'],'runs':runs,'first_rtf':rtf[0],'warm_rtf_median':statistics.median(rtf[1:]),'first_total_seconds':lat[0],'warm_total_seconds_median':statistics.median(lat[1:]),'first_audio_first_seconds':fa[0],'first_audio_warm_median_seconds':statistics.median(fa[1:]),'first_audio_semantics':b['first_audio_semantics'],'memory':{k:b[k] for k in ['rss_after_sessions_kib','peak_vm_hwm_kib','peak_sampled_rss_kib','peak_sampled_pss_kib']},'threads':{k:b[k] for k in ['process_threads_min','process_threads_max','samples']},'cpu_orchestration':b['cpu_orchestration']},'profile_run':{'setup_seconds':pr['setup_seconds'],'runs':pr['runs'],'providers':providers,'physical':physical,'expected_neural_calls':expected},'wav':audio(a.run/f'evidence/{wav_name}',runs[-1]),'thermal':{'benchmark_before':str(a.run/f'thermal-{name}-benchmark-before.txt'),'benchmark_after':str(a.run/f'thermal-{name}-benchmark-after.txt'),'profile_before':str(a.run/f'thermal-{name}-profile-before.txt'),'profile_after':str(a.run/f'thermal-{name}-profile-after.txt')},'power':{'benchmark_before':str(a.run/f'battery-{name}-benchmark-before.txt'),'benchmark_after':str(a.run/f'battery-{name}-benchmark-after.txt'),'profile_before':str(a.run/f'battery-{name}-profile-before.txt'),'profile_after':str(a.run/f'battery-{name}-profile-after.txt')}}
htp=route('htp','QNNExecutionProvider','moss-fixed-all-htp.wav');cpu=route('cpu','CPUExecutionProvider','moss-fixed-cpu.wav');out={'schema_version':1,'result':'passed_matched_cpu_and_full_htp_evidence','canonical_transcript':{'version':2,'bytes':226,'trailing_newline':False,'sha256':'424b38073a00cf48e4c3ebaa246aec0b6549b3ed56a1bf7cfa26d037fb29db67','tokenization':'protocol/canonical-v2-tokenization.json'},'routes':{'cpu':cpu,'all_htp':htp},'comparison':{'warm_generation_speedup_cpu_over_htp':cpu['benchmark']['warm_total_seconds_median']/htp['benchmark']['warm_total_seconds_median'],'warm_rtf_speedup_cpu_over_htp':cpu['benchmark']['warm_rtf_median']/htp['benchmark']['warm_rtf_median'],'audio_duration_difference_seconds':htp['wav']['duration_seconds']-cpu['wav']['duration_seconds']},'execution_order':['htp-benchmark','htp-profile','cpu-benchmark','cpu-profile'],'claim_boundaries':['Every learned HTP-route graph call is one fail-closed QNN partition with QNN-only ORT events and physical RPC/accelerator/cycle/4-HVX evidence.','Matched CPU uses the same canonical-v2 fixed-capacity derivatives but CPUExecutionProvider.','Token/repetition/random orchestration and fixed KV state slot copies execute on CPU in both routes; these are application state work, not neural fallback.','The codec completes before PCM exists, so first-audio is non-streaming full-decode latency.','Benchmark metrics are six-run unprofiled processes; separate one-run profiles establish providers/physical execution and are excluded from timing.','VmHWM, sampled RSS, and sampled PSS are whole-process values. Numerical audio comparison is descriptive; only Moritz sets the route/sample listening verdict.']}
a.output.parent.mkdir(parents=True,exist_ok=True);a.output.write_text(json.dumps(out,indent=2,sort_keys=True)+'\n');print(json.dumps({'cpu_warm_rtf':cpu['benchmark']['warm_rtf_median'],'htp_warm_rtf':htp['benchmark']['warm_rtf_median'],'speedup':out['comparison']['warm_rtf_speedup_cpu_over_htp']},indent=2))
